; =============================================================================
; BANK $80 — a TEXT bank (S150, ROADMAP P3.6; GENERATED by
; editor2/core/gametext.py from gamedata.text — do not hand-edit): the
; project's edits of the game's own texts + the lookup (the HOME bank).
; TEXT_SYSTEM "Edited game text (S150)", PROJECT_COMPILER §2.58.
; =============================================================================

SECTION "ROM Bank $080", ROMX[$4000], BANK[$80]

    db $80                          ; bank self-ID at $4000 (load-bearing)
    dw TextOvrFind_T80                 ; entry 0 — the lookup (bank $60 entry 14)
    dw TextOvrCopy_T80                 ; entry 1 — copy an edited text here to [$C837]

; =============================================================================
; S150 (ROADMAP P3.6 / Phase F T-author) — EDITED GAME TEXT: the lookup.
; Pasted into the text HOME bank only (the first text bank, editor2/core/
; gametext.py), with _T80 = that bank's suffix. Owning docs: TEXT_SYSTEM
; "Edited game text (S150)", PROJECT_COMPILER §2.58.
;
; Every text the game shows or copies is found by ROM0 SaveBankAndSwitch: DE =
; the current bank's mode list, [$C822] = the mode, [$C823] = the id; level 1
; reads the mode's per-id TABLE, level 2 the text's address at table + 2 * id.
; Its level-1 read (ROM0 TextLevel1Hook, $00F0) far-calls bank $60 entry 14
; (TextOverride), which forwards here when the build has edited texts.
;
; In:  DE = the per-id table about to be indexed, [$C823] = the id, [$C824] =
;      the bank that table is in (SaveBankAndSwitch stored [$4000] there),
;      [wTextOvrMode] = 1 when RunTextHandler copies the text into its buffer
;      [$C837] (ROM0 SaveBankAndSwitchCopy set it), else 0.
; Out: an EDITED text (a row of this table holds the id):
;        DE = wTextOvrPtr - 2 * id, so SaveBankAndSwitch's own level-2 read
;        `[DE + 2 * id]` fetches the word in wTextOvrPtr — WRAM, read whatever
;        ROM bank is mapped;
;        show: wTextOvrPtr = the edited text, [$C824] = its bank — the text
;              engine reads every byte from bank [$C824] (ReadNextTextByte,
;              SaveBankForTextDisplay);
;        copy: the text is copied to [$C837] from its own bank (that text
;              bank's entry 1) and wTextOvrPtr = [$C837]: RunTextHandler's loop
;              then copies the buffer onto itself up to the $F0 written here.
;      not edited: DE unchanged. Always: wTextOvrMode = 0, BC / HL clobbered
;      (SaveBankAndSwitch reloads HL; rst $10 hands DE back).
;
; Data (generated below the blocks):
;   TextOvrBanks_T80: 32 bytes — bit (bank & 7) of byte (bank >> 3) set = some
;                    table of that bank has an edited text (the quick "no").
;   TextOvrDir_T80:   per edited table [db bank, dw table, dw list, db count],
;                    ended by a bank $00 byte.
;   a list:          count x [db id, db text bank, dw address] (count 0 = 256).
; =============================================================================
TextOvrFind_T80:
    push de                         ; the table (a miss hands it back)
    ld a, [wTextOvrMode]
    ld c, a                         ; C = 1 copy / 0 show
    xor a
    ld [wTextOvrMode], a
    ld a, [$c824]
    ld b, a                         ; B = the table's bank
    rrca
    rrca
    rrca
    and $1F                         ; the bitmap byte
    ld hl, TextOvrBanks_T80
    add l
    ld l, a
    ld a, h
    adc $00
    ld h, a
    ld e, [hl]
    ld a, b
    and $07                         ; its bit
.shift:
    jr z, .tested
    srl e
    dec a
    jr .shift
.tested:
    bit 0, e
    jr z, .miss
    pop de
    push de
    ld hl, TextOvrDir_T80
.row:
    ld a, [hl+]
    and a
    jr z, .miss                     ; bank $00 ends the rows
    cp b
    jr nz, .skip5
    ld a, [hl+]
    cp e
    jr nz, .skip4
    ld a, [hl+]
    cp d
    jr nz, .skip3
    ld a, [hl+]                     ; this table: its list
    ld e, a
    ld a, [hl+]
    ld d, a
    ld b, [hl]                      ; B = the rows in it
    ld h, d
    ld l, e
    ld a, [$c823]
    ld e, a                         ; E = the id
.item:
    ld a, [hl+]
    cp e
    jr z, .hit
    inc hl
    inc hl
    inc hl
    dec b
    jr nz, .item
    jr .miss
.skip5:
    inc hl
.skip4:
    inc hl
.skip3:
    inc hl
    inc hl
    inc hl
    jr .row
.hit:
    ld a, [hl+]
    ld b, a                         ; B = the edited text's bank
    ld a, [hl+]
    ld e, a
    ld d, [hl]                      ; DE = its address
    pop hl                          ; (the saved table)
    ld a, c
    and a
    jr nz, .copy
    ld a, b
    ld [$c824], a                   ; show: the engine reads it from its bank
    jr .point
.copy:
    ld a, [$4000]
    cp b
    jr nz, .far
    call TextOvrCopy_T80             ; it is in this bank
    jr .copied
.far:
    ld h, b
    ld l, $01
    rst $10                         ; its bank's entry 1 = TextOvrCopy there (DE = the text)
.copied:
    ld a, [$c837]
    ld e, a
    ld a, [$c838]
    ld d, a                         ; the buffer: RunTextHandler copies it onto itself
.point:
    ld a, e
    ld [wTextOvrPtr], a
    ld a, d
    ld [wTextOvrPtr + 1], a
    ld a, [$c823]
    ld l, a
    ld h, $00
    add hl, hl                      ; 2 * id
    ld a, LOW(wTextOvrPtr)
    sub l
    ld e, a
    ld a, HIGH(wTextOvrPtr)
    sbc h
    ld d, a                         ; DE = wTextOvrPtr - 2 * id
    ret
.miss:
    pop de
    ret

; =============================================================================
; S150 (ROADMAP P3.6 / Phase F T-author) — EDITED GAME TEXT: a text bank's copier.
; Pasted into EVERY text bank (the home bank too), _T80 = the bank's suffix;
; entry 1 of each text bank. TEXT_SYSTEM "Edited game text (S150)".
; In: DE = an edited text in THIS bank. Copies it, its closing $F0 included, to
; [$C837] — RunTextHandler's buffer (the copy path: names the game copies into
; a buffer before it prints them, e.g. bank $41's names through ROM0 $0981).
; Clobbers A / DE / HL.
; =============================================================================
TextOvrCopy_T80:
    ld a, [$c837]
    ld l, a
    ld a, [$c838]
    ld h, a
.loop:
    ld a, [de]
    ld [hl+], a
    inc de
    cp $f0
    jr nz, .loop
    ret

; -----------------------------------------------------------------------------
; TEXT DATA (generated — bank $80)
; -----------------------------------------------------------------------------
TextOvrData_T80:
TextOvrBanks_T80:   ; bit (bank & 7) of byte (bank >> 3): a bank with an edited table
    db $00, $00, $00, $00, $00, $00, $00, $00, $02, $00, $00, $00, $00, $00, $00, $00
    db $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00, $00
TextOvrDir_T80:   ; [db bank, dw table, dw list, db rows] per edited table, bank $00 ends
    db $41
    dw $4539, TextOvrList_T80_0
    db 5   ; 5 edited
    db $00
TextOvrList_T80_0:   ; bank $41 table $4539: [db id, db bank, dw text]
    db 234, BANK(TextOvr_skill_name_234)
    dw TextOvr_skill_name_234
    db 235, BANK(TextOvr_skill_name_235)
    dw TextOvr_skill_name_235
    db 236, BANK(TextOvr_skill_name_236)
    dw TextOvr_skill_name_236
    db 237, BANK(TextOvr_skill_name_237)
    dw TextOvr_skill_name_237
    db 238, BANK(TextOvr_skill_name_238)
    dw TextOvr_skill_name_238
TextOvr_skill_name_235:   ; skill_name 235
    db $33, $52, $4B, $46, $50, $45, $F0
TextOvr_skill_name_236:   ; skill_name 236
    db $29, $46, $4B, $46, $50, $45, $F0
TextOvr_skill_name_237:   ; skill_name 237
    db $35, $52, $4D, $51, $52, $4F, $42, $F0
TextOvr_skill_name_238:   ; skill_name 238
    db $25, $49, $52, $4B, $51, $F0
TextOvr_skill_name_234:   ; skill_name 234
    db $33, $49, $52, $4B, $41, $42, $4F, $F0
